<template>
  <div class="page-stack">
    <section class="hero compact"><div><span class="eyebrow">RUNTIME CATALOG</span><h1>模型与 Agent</h1><p>Agent 从本机运行环境发现；模型由服务端从 LiteLLM 网关实时读取。</p></div><el-button type="primary" @click="load" :loading="loading"><el-icon><Refresh/></el-icon> 重新发现</el-button></section>
    <el-alert v-if="modelData.errors?.length" type="warning" show-icon :closable="false"><template #title>部分 LiteLLM 网关不可用，已展示配置文件中的回退模型</template><div v-for="item in modelData.errors" :key="JSON.stringify(item)">{{item.base_url||item.gateway}}：{{item.error}}</div></el-alert>
    <div class="runtime-summary"><div><span class="dot" :class="{on:detectedAgents.length}"/><p><b>{{detectedAgents.length}} / {{agents.length}}</b><small>本机 Agent 可用</small></p></div><div><span class="dot" :class="{on:modelData.litellm_available}"/><p><b>{{models.length}}</b><small>可选模型</small></p></div><div><span class="dot" :class="{on:modelData.litellm_available}"/><p><b>{{modelData.gateways?.length||0}}</b><small>LiteLLM 网关</small></p></div><div><span class="dot" :class="{on:database.ok}"/><p><b>{{database.ok?'正常':'未连接'}}</b><small>评测轨迹数据库</small></p></div></div>
    <el-card shadow="never" class="panel"><template #header><div class="panel-title"><b>本地 Agent</b><span>通过可执行文件 PATH 自动发现</span></div></template><el-table :data="agents" v-loading="loading"><el-table-column label="Agent" width="150"><template #default="{row}"><b>{{row.agent}}</b></template></el-table-column><el-table-column label="可用状态" width="120"><template #default="{row}"><el-tag :type="row.detected_executable?'success':'info'">{{row.detected_executable?'已检测':'未检测'}}</el-tag></template></el-table-column><el-table-column prop="detected_executable" label="本地路径" min-width="300"><template #default="{row}"><code>{{row.detected_executable||row.default_command}}</code></template></el-table-column><el-table-column label="能力" min-width="260"><template #default="{row}"><div class="tags"><el-tag v-for="cap in capabilityTags(row)" :key="cap" effect="plain" size="small">{{cap}}</el-tag></div></template></el-table-column></el-table></el-card>
    <el-card shadow="never" class="panel"><template #header><div class="panel-title"><b>可用模型</b><span>{{modelData.litellm_available?'已从 LiteLLM 实时同步':'当前为本地配置回退'}}</span></div></template><div class="toolbar"><el-input v-model="keyword" :prefix-icon="Search" clearable placeholder="搜索模型或 Profile"/><el-tag :type="modelData.litellm_available?'success':'warning'">{{modelData.litellm_available?'LiteLLM 在线':'使用回退配置'}}</el-tag></div><el-table :data="filteredModels" max-height="520"><el-table-column prop="id" label="模型" min-width="260"><template #default="{row}"><b>{{row.id}}</b></template></el-table-column><el-table-column prop="profile" label="配置 Profile" min-width="170"/><el-table-column label="来源" width="130"><template #default="{row}"><el-tag effect="plain">{{row.source}}</el-tag></template></el-table-column><el-table-column prop="owned_by" label="供应方" min-width="150"/></el-table></el-card>
    <el-card shadow="never" class="panel"><template #header><div class="panel-title"><b>题库运行 Provider</b><span>由统一评测入口按 Agent/模型自动管理</span></div></template><el-table :data="providers"><el-table-column prop="name" label="Provider" min-width="220"/><el-table-column prop="kind" label="执行方式" min-width="160"/><el-table-column prop="model" label="模型" min-width="220"/><el-table-column prop="base_url" label="网关" min-width="220"/></el-table><el-empty v-if="!providers.length" description="首次运行题库评测时将自动创建 Provider"/></el-card>
  </div>
</template>
<script setup>
import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{Search}from'@element-plus/icons-vue';import{fetchAgents,fetchDatabaseHealth,fetchModels,fetchProviders}from'../api'
const agents=ref([]),modelData=ref({models:[],gateways:[],errors:[]}),database=ref({}),providers=ref([]),keyword=ref(''),loading=ref(false);const models=computed(()=>modelData.value.models||[]),detectedAgents=computed(()=>agents.value.filter(x=>x.detected_executable)),filteredModels=computed(()=>models.value.filter(x=>`${x.id} ${x.profile} ${x.owned_by}`.toLowerCase().includes(keyword.value.toLowerCase())))
function capabilityTags(row){const c=row.capabilities||{};return Object.entries(c).filter(([,v])=>v===true).map(([k])=>({skill_injection:'Skill 注入',model_selection:'模型选择',structured_output:'结构化输出',repository_tasks:'仓库任务'}[k]||k)).slice(0,5)}
async function load(){loading.value=true;const r=await Promise.allSettled([fetchAgents(),fetchModels(),fetchDatabaseHealth(),fetchProviders()]);agents.value=r[0].status==='fulfilled'?r[0].value:[];modelData.value=r[1].status==='fulfilled'?r[1].value:{models:[],gateways:[],errors:[{error:r[1].reason?.message}]};database.value=r[2].status==='fulfilled'?r[2].value:{};providers.value=r[3].status==='fulfilled'?r[3].value:[];if(r.every(x=>x.status==='rejected'))ElMessage.error('无法读取运行环境');loading.value=false}onMounted(load)
</script>
<style scoped>
.runtime-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.runtime-summary>div{display:flex;align-items:center;gap:13px;padding:18px;background:var(--surface);border:1px solid var(--line);border-radius:13px}.runtime-summary p{display:flex;flex-direction:column;margin:0}.runtime-summary b{font-size:20px}.runtime-summary small,.panel-title span{color:var(--muted)}.dot{width:12px;height:12px;border-radius:50%;background:#a6adba;box-shadow:0 0 0 5px rgba(166,173,186,.12)}.dot.on{background:#25a66a;box-shadow:0 0 0 5px rgba(37,166,106,.12)}.panel-title,.toolbar,.tags{display:flex;align-items:center;justify-content:space-between;gap:10px}.toolbar{margin-bottom:16px}.toolbar .el-input{max-width:360px}.tags{justify-content:flex-start;flex-wrap:wrap}code{font-size:12px;color:var(--muted)}@media(max-width:800px){.runtime-summary{grid-template-columns:repeat(2,1fr)}}
</style>
